actions.script:
import org.moqui.BaseException

def rr = ec.resource.getLocationReference(imageLocation)
if (rr == null) throw new BaseException("Could not resolve image location ${imageLocation}.")
byte[] imageBytes
rr.openStream().withStream { stream -> imageBytes = stream.bytes }
if (!imageBytes) throw new BaseException("Image at ${imageLocation} is empty.")

imageBase64 = imageBytes.encodeBase64().toString()
String baseUrl = (openVlaBaseUrl ?: "http://openvla:8000").replaceAll('/+$', '')
openVlaLocation = apiKey ? "${baseUrl}/act?apiKey=${java.net.URLEncoder.encode(apiKey, 'UTF-8')}" : "${baseUrl}/act"

import org.moqui.BaseException

def rr = ec.resource.getLocationReference(imageLocation)
if (rr == null) throw new BaseException("Could not resolve image location ${imageLocation}.")
byte[] imageBytes
rr.openStream().withStream { stream -> imageBytes = stream.bytes }
if (!imageBytes) throw new BaseException("Image at ${imageLocation} is empty.")

imageBase64 = imageBytes.encodeBase64().toString()
String baseUrl = (openVlaBaseUrl ?: "http://openvla:8000").replaceAll('/+$', '')
openVlaLocation = apiKey ? "${baseUrl}/ground?apiKey=${java.net.URLEncoder.encode(apiKey, 'UTF-8')}" : "${baseUrl}/ground"

import org.moqui.BaseException
def normalizeNumberList = { Object value, String fieldName, Integer minSize = null -> if (value == null) return null List<?> sourceList = value instanceof List ? (List<?>) value : [value] List<BigDecimal> normalized = [] sourceList.eachWithIndex { Object entry, int idx -> if (entry == null || entry.toString().trim().isEmpty()) { throw new BaseException("${fieldName}[${idx}] is empty.") } normalized.add(new BigDecimal(entry.toString())) } if (minSize != null && normalized.size() < minSize) { throw new BaseException("${fieldName} must contain at least ${minSize} values.") } return normalized }
List<BigDecimal> boundingBoxList = normalizeNumberList(groundingResult.boundingBox, "boundingBox", 4) List<BigDecimal> centerList = normalizeNumberList(groundingResult.center, "center", 2) List<BigDecimal> targetPoseList = normalizeNumberList(groundingResult.targetPose, "targetPose", returnTargetPose ? (targetPoseDimension ?: 6) : null)
if (!boundingBoxList && !centerList && !targetPoseList) { throw new BaseException("OpenVLA grounding response for device ${deviceId} did not contain boundingBox, center, or targetPose.") }
boundingBox = boundingBoxList center = centerList targetPose = targetPoseList goalPose = targetPoseList objectLabel = groundingResult.objectLabel confidence = groundingResult.confidence coordinateSystem = groundingResult.coordinateSystem ?: "image-pixel" modelId = groundingResult.modelId

import org.moqui.BaseException import groovy.json.JsonOutput import org.moqui.device.TrajectoryGenerator
if (startPose == null) throw new BaseException("Missing startPose.") if (goalPose == null) throw new BaseException("Missing goalPose.")
startPoseList = TrajectoryGenerator.normalizePoseVector(startPose, "startPose") goalPoseList = TrajectoryGenerator.normalizePoseVector(goalPose, "goalPose") mathModelRunParameters = JsonOutput.toJson([startPose: startPoseList, goalPose: goalPoseList]) trajectoryLabel = trajectoryName ?: null

import groovy.json.JsonOutput
import org.moqui.context.ExecutionContext
import org.moqui.device.TrajectoryGenerator

ExecutionContext ec = context.ec

try {
    Map inference = TrajectoryGenerator.runInference(ec, onnxContent.contentLocation as String,
        startPoseList, goalPoseList)
    waypoints = inference.waypoints
    waypointCount = inference.waypointCount
    inferenceLatencyMs = inference.inferenceLatencyMs ?: 0L
} catch (Throwable t) {
    long elapsed = System.currentTimeMillis() - t0
    def runRef = ec.entity.find("moqui.math.MathModelRun").condition("mathModelRunId", runId).one()
    if (runRef) {
        runRef.setAll([endDate : ec.user.nowTimestamp, runningTimeMillis: (float) elapsed,
            hasError : 'Y', errors : t.message])
        runRef.update()
    }
    throw t
}
